export enum AgentStatus {
  IDLE = 'IDLE',
  THINKING = 'THINKING',
  EXECUTING = 'EXECUTING',
  LEARNING = 'LEARNING',
  ERROR = 'ERROR'
}

export interface Memory {
  id: string;
  type: 'fact' | 'instruction' | 'observation' | 'insight';
  content: string;
  timestamp: number;
  importance: number;
}

export interface Thought {
  id: string;
  timestamp: number;
  content: string;
  type: 'plan' | 'observation' | 'conclusion' | 'error';
}

export interface Task {
  id: string;
  goal: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed';
  subtasks: string[];
  results?: string;
}

export interface AgentState {
  status: AgentStatus;
  memories: Memory[];
  thoughts: Thought[];
  currentTask: Task | null;
  history: {role: 'user' | 'model', content: string}[];
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Thought, Memory, AgentStatus } from "../types";

const API_KEY = process.env.API_KEY || "";

export class GeminiAgentService {
  private ai: GoogleGenAI;
  private modelName = "gemini-3-pro-preview";

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: API_KEY });
  }

  async planAndExecute(
    goal: string, 
    memories: Memory[], 
    onThought: (thought: Thought) => void,
    onStatusChange: (status: AgentStatus) => void
  ): Promise<string> {
    onStatusChange(AgentStatus.THINKING);

    const context = memories.map(m => `[${m.type.toUpperCase()}] ${m.content}`).join('\n');

    const systemPrompt = `
      You are an Autonomous AI Agent named Aether. 
      Your goal: ${goal}

      Your Memory Context:
      ${context}

      Operational Protocol:
      1. Analyze the goal.
      2. Break it down into logical steps.
      3. Execute each step using internal reasoning and web search if needed.
      4. If you encounter an error, pivot and try a different approach.
      5. Summarize your final findings clearly.

      You must think step-by-step. Provide your reasoning before each action.
    `;

    try {
      const response = await this.ai.models.generateContent({
        model: this.modelName,
        contents: goal,
        config: {
          systemInstruction: systemPrompt,
          thinkingConfig: { thinkingBudget: 16000 },
          tools: [{ googleSearch: {} }]
        },
      });

      onStatusChange(AgentStatus.EXECUTING);

      // Simulate multiple steps if it's a complex goal
      // In a real autonomous agent, we would loop here based on the model's output

      const finalOutput = response.text || "I was unable to formulate a complete response.";

      onThought({
        id: Math.random().toString(36),
        timestamp: Date.now(),
        content: `Completed task: ${goal.substring(0, 30)}...`,
        type: 'conclusion'
      });

      return finalOutput;
    } catch (error) {
      console.error("Agent Execution Error:", error);
      onStatusChange(AgentStatus.ERROR);
      return "An error occurred during execution.";
    }
  }

  async generateMemoryInsight(thoughts: Thought[]): Promise<Memory[]> {
    const text = thoughts.map(t => t.content).join('\n');
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Based on these thoughts, extract 1-3 key long-term memories or facts to store:\n${text}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              content: { type: Type.STRING },
              type: { type: Type.STRING, enum: ['fact', 'instruction', 'observation', 'insight'] },
              importance: { type: Type.NUMBER }
            },
            required: ['content', 'type', 'importance']
          }
        }
      }
    });

    try {
      const insights = JSON.parse(response.text || "[]");
      return insights.map((i: any) => ({
        ...i,
        id: Math.random().toString(36),
        timestamp: Date.now()
      }));
    } catch {
      return [];
    }
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AgentStatus, AgentState, Thought, Memory, Task } from './types';
import { GeminiAgentService } from './services/gemini';
import Sidebar from './components/Sidebar';
import ThoughtProcess from './components/ThoughtProcess';
import MemoryGrid from './components/MemoryGrid';
import AgentControl from './components/AgentControl';
import { Brain, Cpu, Database, Activity, Terminal } from 'lucide-react';

const App: React.FC = () => {
  const [state, setState] = useState<AgentState>({
    status: AgentStatus.IDLE,
    memories: [
      { id: '1', type: 'instruction', content: 'Always prioritize data accuracy and search grounding.', timestamp: Date.now(), importance: 0.9 },
      { id: '2', type: 'fact', content: 'Agent Aether initialized in the cloud environment.', timestamp: Date.now(), importance: 0.5 }
    ],
    thoughts: [],
    currentTask: null,
    history: []
  });

  const agentRef = useRef<GeminiAgentService | null>(null);

  useEffect(() => {
    agentRef.current = new GeminiAgentService();
  }, []);

  const addThought = useCallback((thought: Thought) => {
    setState(prev => ({
      ...prev,
      thoughts: [thought, ...prev.thoughts].slice(0, 50)
    }));
  }, []);

  const handleRunTask = async (goal: string) => {
    if (!agentRef.current || !goal) return;

    const newTask: Task = {
      id: Math.random().toString(36),
      goal,
      status: 'in_progress',
      subtasks: []
    };

    setState(prev => ({ 
      ...prev, 
      currentTask: newTask,
      status: AgentStatus.THINKING
    }));

    addThought({
      id: Math.random().toString(36),
      timestamp: Date.now(),
      content: `Received objective: ${goal}`,
      type: 'plan'
    });

    const result = await agentRef.current.planAndExecute(
      goal,
      state.memories,
      addThought,
      (status) => setState(prev => ({ ...prev, status }))
    );

    // Extract new memories from the session
    const newMemories = await agentRef.current.generateMemoryInsight([{
      id: 'res',
      timestamp: Date.now(),
      content: result,
      type: 'conclusion'
    }, ...state.thoughts.slice(0, 5)]);

    setState(prev => ({
      ...prev,
      status: AgentStatus.IDLE,
      memories: [...newMemories, ...prev.memories].slice(0, 100),
      currentTask: prev.currentTask ? { ...prev.currentTask, status: 'completed', results: result } : null
    }));
  };

  return (
    <div className="flex h-screen bg-gray-950 text-gray-100 overflow-hidden">
      {/* Navigation / Status Sidebar */}
      <Sidebar status={state.status} memoriesCount={state.memories.length} />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        {/* Header */}
        <header className="h-16 border-b border-gray-800 flex items-center justify-between px-8 bg-gray-950/50 backdrop-blur-md z-10">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-lg bg-indigo-500/10 text-indigo-400 border border-indigo-500/20`}>
              <Cpu size={20} />
            </div>
            <div>
              <h1 className="text-lg font-bold tracking-tight">Aether Core</h1>
              <p className="text-xs text-gray-500 font-medium">Autonomous Agent Instance v3.1</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2">
              <div className={`w-2 h-2 rounded-full ${state.status !== AgentStatus.IDLE ? 'bg-green-500 animate-pulse' : 'bg-gray-600'}`} />
              <span className="text-xs font-mono uppercase text-gray-400">{state.status}</span>
            </div>
            <div className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors cursor-help">
              <Activity size={16} />
              <span className="text-xs">Lat: 142ms</span>
            </div>
          </div>
        </header>

        {/* Dashboard Content */}
        <div className="flex-1 grid grid-cols-12 gap-6 p-6 overflow-hidden">
          {/* Left Column: Thought Stream & Current Action */}
          <div className="col-span-12 lg:col-span-7 flex flex-col gap-6 overflow-hidden">
            <section className="flex-1 min-h-0 bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden flex flex-col">
              <div className="px-4 py-3 border-b border-gray-800 flex items-center justify-between bg-gray-900/50">
                <div className="flex items-center gap-2 text-sm font-semibold text-gray-300">
                  <Terminal size={16} className="text-indigo-400" />
                  Live Thinking Stream
                </div>
              </div>
              <ThoughtProcess thoughts={state.thoughts} />
            </section>

            <section className="h-48 bg-gray-900/40 border border-gray-800 rounded-2xl p-6 flex flex-col justify-center">
              <AgentControl onRun={handleRunTask} status={state.status} />
            </section>
          </div>

          {/* Right Column: Memory & Knowledge Base */}
          <div className="col-span-12 lg:col-span-5 flex flex-col gap-6 overflow-hidden">
            <section className="flex-1 min-h-0 bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden flex flex-col">
              <div className="px-4 py-3 border-b border-gray-800 flex items-center justify-between bg-gray-900/50">
                <div className="flex items-center gap-2 text-sm font-semibold text-gray-300">
                  <Database size={16} className="text-emerald-400" />
                  Active Memory Clusters
                </div>
                <span className="text-[10px] text-gray-500 font-mono">NEURAL_STORAGE_v4</span>
              </div>
              <MemoryGrid memories={state.memories} />
            </section>

            <section className="h-48 bg-gray-900/40 border border-gray-800 rounded-2xl p-6 flex flex-col justify-between relative group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                <Brain size={80} />
              </div>
              <div>
                <h3 className="text-sm font-semibold text-gray-300 mb-2">Agent Statistics</h3>
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-gray-950/50 p-3 rounded-xl border border-gray-800/50">
                    <p className="text-[10px] text-gray-500 uppercase font-bold">Inferences</p>
                    <p className="text-xl font-mono text-indigo-400">1,248</p>
                  </div>
                  <div className="bg-gray-950/50 p-3 rounded-xl border border-gray-800/50">
                    <p className="text-[10px] text-gray-500 uppercase font-bold">Memory Health</p>
                    <p className="text-xl font-mono text-emerald-400">99.8%</p>
                  </div>
                </div>
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

