import React, { useEffect, useRef } from 'react';
import { Thought } from '../types';
import { CheckCircle, AlertCircle, Search, Compass, Loader2 } from 'lucide-react';

interface ThoughtProcessProps {
  thoughts: Thought[];
}

const ThoughtProcess: React.FC<ThoughtProcessProps> = ({ thoughts }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = 0;
    }
  }, [thoughts]);

  const getTypeIcon = (type: Thought['type']) => {
    switch (type) {
      case 'plan': return <Compass size={14} className="text-blue-400" />;
      case 'observation': return <Search size={14} className="text-amber-400" />;
      case 'conclusion': return <CheckCircle size={14} className="text-emerald-400" />;
      case 'error': return <AlertCircle size={14} className="text-rose-400" />;
    }
  };

  const getTypeStyles = (type: Thought['type']) => {
    switch (type) {
      case 'plan': return 'border-blue-500/20 bg-blue-500/5';
      case 'observation': return 'border-amber-500/20 bg-amber-500/5';
      case 'conclusion': return 'border-emerald-500/20 bg-emerald-500/5';
      case 'error': return 'border-rose-500/20 bg-rose-500/5';
    }
  };

  return (
    <div 
      ref={containerRef}
      className="flex-1 overflow-y-auto p-4 space-y-4 font-mono text-sm custom-scrollbar scroll-smooth"
    >
      {thoughts.length === 0 && (
        <div className="h-full flex flex-col items-center justify-center text-gray-600 space-y-2 opacity-50">
          <Loader2 className="animate-spin" size={24} />
          <p className="text-xs">Waiting for objective...</p>
        </div>
      )}

      {thoughts.map((thought) => (
        <div 
          key={thought.id}
          className={`group relative p-4 rounded-xl border transition-all animate-in fade-in slide-in-from-top-2 duration-300 ${getTypeStyles(thought.type)}`}
        >
          <div className="flex items-start gap-3">
            <div className="mt-1">
              {getTypeIcon(thought.type)}
            </div>
            <div className="flex-1">
              <div className="flex items-center justify-between mb-1">
                <span className="text-[10px] uppercase font-bold tracking-widest opacity-60">
                  {thought.type}
                </span>
                <span className="text-[10px] opacity-40">
                  {new Date(thought.timestamp).toLocaleTimeString([], { hour12: false })}
                </span>
              </div>
              <p className="text-gray-300 leading-relaxed whitespace-pre-wrap">
                {thought.content}
              </p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default ThoughtProcess;

