              <p className="text-xs text-gray-300 leading-normal line-clamp-3">
                {memory.content}
              </p>
              <div className="mt-2 flex items-center gap-2 opacity-40">
                <span className="text-[9px] font-mono">{memory.type.toUpperCase()}</span>
                <span className="w-1 h-1 rounded-full bg-gray-600" />
                <span className="text-[9px] font-mono">IMP: {Math.round(memory.importance * 100)}%</span>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default MemoryGrid;

import React, { useState } from 'react';
import { AgentStatus } from '../types';
import { Send, Zap, Square } from 'lucide-react';

interface AgentControlProps {
  onRun: (goal: string) => void;
  status: AgentStatus;
}

const AgentControl: React.FC<AgentControlProps> = ({ onRun, status }) => {
  const [input, setInput] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && status === AgentStatus.IDLE) {
      onRun(input);
      setInput('');
    }
  };

  const isBusy = status !== AgentStatus.IDLE;

  return (
    <div className="w-full">
      <h3 className="text-sm font-semibold text-gray-300 mb-3 flex items-center gap-2">
        <Zap size={16} className="text-indigo-400" />
        Mission Objective
      </h3>
      <form onSubmit={handleSubmit} className="relative group">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder={isBusy ? "Agent is currently engaged..." : "Enter mission parameters (e.g., 'Research the latest advancements in quantum computing')"}
          disabled={isBusy}
          className="w-full bg-gray-950 border border-gray-800 rounded-2xl py-4 pl-5 pr-14 text-sm focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/20 transition-all placeholder:text-gray-600"
        />
        <button
          type="submit"
          disabled={isBusy || !input.trim()}
          className={`absolute right-2 top-2 bottom-2 w-10 flex items-center justify-center rounded-xl transition-all ${
            isBusy 
            ? 'bg-gray-800 text-gray-600 cursor-not-allowed' 
            : input.trim() 
              ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20 hover:bg-indigo-500' 
              : 'bg-gray-900 text-gray-700'
          }`}
        >
          {isBusy ? (
            <div className="flex gap-1">
              <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" />
              <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce delay-75" />
              <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce delay-150" />
            </div>
          ) : (
            <Send size={18} />
          )}
        </button>
      </form>
      <div className="mt-3 flex gap-2">
        {['Market Analysis', 'Write Code', 'Scientific Research'].map((tag) => (
          <button
            key={tag}
            disabled={isBusy}
            onClick={() => setInput(prev => `${prev} ${tag}`.trim())}
            className="text-[10px] font-bold uppercase tracking-wider text-gray-500 hover:text-indigo-400 transition-colors border border-gray-800 px-2 py-1 rounded-md bg-gray-900/50"
          >
            +{tag}
          </button>
        ))}
      </div>
    </div>
  );
};

export default AgentControl;

