      {/* Navigation / Status Sidebar */}
      <Sidebar 
        status={state.status} 
        memoriesCount={state.memories.length} 
        currentView={state.view}
        onSetView={setView}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        {/* Header */}
        <header className="h-16 border-b border-gray-800 flex items-center justify-between px-8 bg-gray-950/50 backdrop-blur-md z-10">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-lg bg-indigo-500/10 text-indigo-400 border border-indigo-500/20`}>
              <Cpu size={20} />
            </div>
            <div>
              <h1 className="text-lg font-bold tracking-tight">Aether Core</h1>
              <p className="text-xs text-gray-500 font-medium">Autonomous Agent Instance v3.1</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2">
              <div className={`w-2 h-2 rounded-full ${state.status !== AgentStatus.IDLE ? 'bg-green-500 animate-pulse' : 'bg-gray-600'}`} />
              <span className="text-xs font-mono uppercase text-gray-400">{state.status}</span>
            </div>
            <div className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors cursor-help">
              <Activity size={16} />
              <span className="text-xs">Lat: 142ms</span>
            </div>
          </div>
        </header>

        {/* Dashboard Content */}
        <div className="flex-1 grid grid-cols-12 gap-6 p-6 overflow-hidden">
          {/* Left Column: Thought Stream & Current Action */}
          <div className="col-span-12 lg:col-span-7 flex flex-col gap-6 overflow-hidden">
            <section className="flex-1 min-h-0 bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden flex flex-col">
              <div className="px-4 py-3 border-b border-gray-800 flex items-center justify-between bg-gray-900/50">
                <div className="flex items-center gap-2 text-sm font-semibold text-gray-300">
                  <Terminal size={16} className="text-indigo-400" />
                  Live Thinking Stream
                </div>
              </div>
              <ThoughtProcess thoughts={state.thoughts} />
            </section>

            <section className="h-48 bg-gray-900/40 border border-gray-800 rounded-2xl p-6 flex flex-col justify-center">
              <AgentControl onRun={handleRunTask} status={state.status} />
            </section>
          </div>

          {/* Right Column: Memory & Knowledge Base */}
          <div className="col-span-12 lg:col-span-5 flex flex-col gap-6 overflow-hidden">
            <section className="flex-1 min-h-0 bg-gray-900/40 border border-gray-800 rounded-2xl overflow-hidden flex flex-col">
              <div className="px-4 py-3 border-b border-gray-800 flex items-center justify-between bg-gray-900/50">
                <div className="flex items-center gap-2 text-sm font-semibold text-gray-300">
                  <Database size={16} className="text-emerald-400" />
                  Active Memory Clusters
                </div>
                <span className="text-[10px] text-gray-500 font-mono">NEURAL_STORAGE_v4</span>
              </div>
              <MemoryGrid memories={state.memories} />
            </section>

            <section className="h-48 bg-gray-900/40 border border-gray-800 rounded-2xl p-6 flex flex-col justify-between relative group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                <Brain size={80} />
              </div>
              <div>
                <h3 className="text-sm font-semibold text-gray-300 mb-2">Agent Statistics</h3>
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-gray-950/50 p-3 rounded-xl border border-gray-800/50">
                    <p className="text-[10px] text-gray-500 uppercase font-bold">Inferences</p>
                    <p className="text-xl font-mono text-indigo-400">1,248</p>
                  </div>
                  <div className="bg-gray-950/50 p-3 rounded-xl border border-gray-800/50">
                    <p className="text-[10px] text-gray-500 uppercase font-bold">Memory Health</p>
                    <p className="text-xl font-mono text-emerald-400">99.8%</p>
                  </div>
                </div>
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
};

