import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AgentStatus, AgentState, Thought, Memory, Task, AppView } from './types';
import { GeminiAgentService } from './services/gemini';
import Sidebar from './components/Sidebar';
import ThoughtProcess from './components/ThoughtProcess';
import MemoryGrid from './components/MemoryGrid';
import AgentControl from './components/AgentControl';
import LiveTerminal from './components/LiveTerminal';
import ImageStudio from './components/ImageStudio';
import { Brain, Cpu, Database, Activity, Terminal, Shield } from 'lucide-react';

const App: React.FC = () => {
  const [state, setState] = useState<AgentState>({
    status: AgentStatus.IDLE,
    memories: [
      { id: '1', type: 'instruction', content: 'Utilize Kimi-class autonomous reasoning for all mission objectives.', timestamp: Date.now(), importance: 1.0 },
      { id: '2', type: 'fact', content: 'Aether Agent Core v3.0 successfully initialized.', timestamp: Date.now(), importance: 0.8 }
    ],
    thoughts: [],
    currentTask: null,
    history: [],
    view: 'DASHBOARD'
  });

  const agentRef = useRef<GeminiAgentService | null>(null);

  useEffect(() => {
    agentRef.current = new GeminiAgentService();
  }, []);

  const addThought = useCallback((thought: Thought) => {
    setState(prev => ({
      ...prev,
      thoughts: [thought, ...prev.thoughts].slice(0, 50)
    }));
  }, []);

  const handleRunTask = async (goal: string) => {
    if (!agentRef.current || !goal) return;

    const newTask: Task = {
      id: Math.random().toString(36),
      goal,
      status: 'in_progress',
      subtasks: []
    };

    setState(prev => ({ 
      ...prev, 
      currentTask: newTask,
      status: AgentStatus.THINKING
    }));

    addThought({
      id: Math.random().toString(36),
      timestamp: Date.now(),
      content: `KIMI_CORE: Initiating heuristic scan for objective: "${goal}"`,
      type: 'plan'
    });

    const result = await agentRef.current.planAndExecute(
      goal,
      state.memories,
      addThought,
      (status) => setState(prev => ({ ...prev, status }))
    );

    const newMemories = await agentRef.current.generateMemoryInsight([{
      id: 'res',
      timestamp: Date.now(),
      content: result,
      type: 'conclusion'
    }, ...state.thoughts.slice(0, 5)]);

    setState(prev => ({
      ...prev,
      status: AgentStatus.IDLE,
      memories: [...newMemories, ...prev.memories].slice(0, 100),
      currentTask: prev.currentTask ? { ...prev.currentTask, status: 'completed', results: result } : null
    }));
  };

  const setView = (view: AppView) => setState(prev => ({ ...prev, view }));

  const renderContent = () => {
    switch(state.view) {
      case 'IMAGE_STUDIO':
        return <ImageStudio />;
      case 'DASHBOARD':
        return (
          <div className="flex-1 grid grid-cols-12 gap-6 p-6 overflow-hidden animate-in fade-in duration-1000">
            {/* Left Column: Thought Stream */}
            <div className="col-span-12 lg:col-span-7 flex flex-col gap-6 overflow-hidden">
              <section className="flex-1 min-h-0 bg-gray-900/30 backdrop-blur-sm border border-gray-800 rounded-3xl overflow-hidden flex flex-col shadow-2xl shadow-indigo-500/5">
                <div className="px-6 py-4 border-b border-gray-800 flex items-center justify-between bg-gray-950/40">
                  <div className="flex items-center gap-3">
                    <div className="p-1.5 bg-indigo-500/10 rounded-lg text-indigo-400">
                      <Terminal size={16} />
                    </div>
                    <span className="text-sm font-bold tracking-tight text-gray-200">Neural Log Stream</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-mono text-gray-500">SYS_AUTH_LEVEL: OVERRIDE</span>
                  </div>
                </div>
                <ThoughtProcess thoughts={state.thoughts} />
              </section>

              <section className="h-44 bg-gray-900/30 backdrop-blur-sm border border-gray-800 rounded-3xl p-6 flex flex-col justify-center shadow-lg">
                <AgentControl onRun={handleRunTask} status={state.status} />
              </section>
            </div>

            {/* Right Column: Memory & Knowledge */}
            <div className="col-span-12 lg:col-span-5 flex flex-col gap-6 overflow-hidden">
              <section className="flex-1 min-h-0 bg-gray-900/30 backdrop-blur-sm border border-gray-800 rounded-3xl overflow-hidden flex flex-col shadow-2xl">
                <div className="px-6 py-4 border-b border-gray-800 flex items-center justify-between bg-gray-950/40">
                  <div className="flex items-center gap-3">
                    <div className="p-1.5 bg-emerald-500/10 rounded-lg text-emerald-400">
                      <Database size={16} />
                    </div>
                    <span className="text-sm font-bold tracking-tight text-gray-200">Long-term Memory Bank</span>
                  </div>
                </div>
                <MemoryGrid memories={state.memories} />
              </section>

              <section className="h-44 bg-gradient-to-br from-indigo-900/20 to-purple-900/10 border border-indigo-500/20 rounded-3xl p-6 flex flex-col justify-between relative group overflow-hidden shadow-2xl">
                <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-all group-hover:scale-110 duration-700">
                  <Brain size={140} />
                </div>
                <div className="relative z-10">
                  <h3 className="text-sm font-bold text-gray-200 mb-4 flex items-center gap-2">
                    <Shield size={16} className="text-indigo-400" />
                    Agent Performance Indices
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-gray-950/40 p-4 rounded-2xl border border-gray-800/50 backdrop-blur-md">
                      <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest mb-1">Heuristic Depth</p>
                      <p className="text-2xl font-mono font-bold text-indigo-400 tracking-tighter">98.4<span className="text-xs ml-1">%</span></p>
                    </div>
                    <div className="bg-gray-950/40 p-4 rounded-2xl border border-gray-800/50 backdrop-blur-md">
                      <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest mb-1">Synaptic Health</p>
                      <p className="text-2xl font-mono font-bold text-emerald-400 tracking-tighter">MAX</p>
                    </div>
                  </div>
                </div>
              </section>
            </div>
          </div>
        );
      default:
        return <div className="flex-1 flex items-center justify-center text-gray-600 font-mono text-sm">MODULE_UNDER_CONSTRUCTION</div>;
    }
  };

  return (
    <div className="flex h-screen bg-[#02040a] text-gray-100 overflow-hidden font-inter selection:bg-indigo-500/30">
      {state.view === 'LIVE_TERMINAL' && (
        <LiveTerminal onClose={() => setView('DASHBOARD')} />
      )}

      {/* Sidebar Navigation */}
      <Sidebar 
        status={state.status} 
        memoriesCount={state.memories.length} 
        currentView={state.view}
        onSetView={setView}
      />

      {/* Main Framework */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        {/* Modern Header */}
        <header className="h-20 border-b border-gray-800/50 flex items-center justify-between px-10 bg-[#02040a]/80 backdrop-blur-xl z-10">
          <div className="flex items-center gap-4">
            <div className="relative">
              <div className="absolute inset-0 bg-indigo-500 rounded-xl blur-lg opacity-20" />
              <div className="relative p-2.5 rounded-xl bg-gray-900 border border-gray-800 text-indigo-400 shadow-inner">
                <Cpu size={22} />
              </div>
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-black tracking-tight bg-gradient-to-r from-white to-gray-500 bg-clip-text text-transparent">AETHER CORE</h1>
                <span className="px-1.5 py-0.5 rounded bg-indigo-500/10 border border-indigo-500/20 text-[9px] font-black text-indigo-400 tracking-tighter uppercase">PRO_LINK</span>
              </div>
              <p className="text-[10px] text-gray-600 font-mono tracking-widest mt-0.5">HEURISTIC_REASONING_SYSTEM_v3.2</p>
            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer">
              <div className="flex flex-col items-end">
                <span className="text-[10px] font-bold text-gray-500 tracking-widest uppercase">System Status</span>
                <span className="text-xs font-mono font-bold text-gray-300">{state.status}</span>
              </div>
              <div className="relative flex items-center justify-center">
                <div className={`absolute w-3 h-3 rounded-full blur-sm ${state.status !== AgentStatus.IDLE ? 'bg-indigo-500' : 'bg-gray-600'}`} />
                <div className={`relative w-2.5 h-2.5 rounded-full border-2 border-black ${state.status !== AgentStatus.IDLE ? 'bg-indigo-400 animate-pulse' : 'bg-gray-700'}`} />
