        </header>

        {/* Dynamic Route Content */}
        {renderContent()}

        {/* Global Footer Decor */}
        <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-indigo-500/20 to-transparent pointer-events-none" />
      </main>
