    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: this.imageModel,
        contents: {
          parts: [
            { inlineData: { data: base64Image, mimeType } },
            { text: prompt }
          ]
        }
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      return null;
    } catch (error) {
      console.error("Image Edit Error:", error);
      return null;
    }
  }

  async generateVideo(prompt: string, config: { resolution: '720p' | '1080p', aspectRatio: '16:9' | '9:16' }): Promise<string | null> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let operation = await ai.models.generateVideos({
        model: this.videoModel,
        prompt: prompt,
        config: {
          numberOfVideos: 1,
          resolution: config.resolution,
          aspectRatio: config.aspectRatio
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (!downloadLink) return null;

      const videoResponse = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
      const blob = await videoResponse.blob();
      return URL.createObjectURL(blob);
    } catch (error) {
      console.error("Video Generation Error:", error);
      return null;
    }
  }

  async generateMemoryInsight(thoughts: Thought[]): Promise<Memory[]> {
    const text = thoughts.map(t => t.content).join('\n');
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Perform high-level knowledge extraction from these logs:\n${text}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              content: { type: Type.STRING },
              type: { 
                type: Type.STRING,
                description: "The category of the insight: 'fact', 'instruction', 'observation', or 'insight'"
              },
              importance: { type: Type.NUMBER }
            },
            required: ['content', 'type', 'importance']
          }
        }
      }
    });

    try {
      const insights = JSON.parse(response.text || "[]");
      return insights.map((i: any) => ({
        ...i,
        id: Math.random().toString(36),
        timestamp: Date.now()
      }));
    } catch {
      return [];
    }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { GeminiAgentService } from '../services/gemini';
import { Upload, Wand2, Download, Image as ImageIcon, Loader2, Sparkles, RefreshCcw, Video, Film, MousePointer2, Settings2, Info, Lock } from 'lucide-react';

type StudioMode = 'EDIT' | 'GENERATE' | 'VIDEO';

export default function ImageStudio() {
  const [mode, setMode] = useState<StudioMode>('GENERATE');
