      { id: '1', type: 'instruction', content: 'Utilize Kimi-class autonomous reasoning for all mission objectives.', timestamp: Date.now(), importance: 1.0 },
      { id: '2', type: 'fact', content: 'Aether Agent Core v3.0 successfully initialized.', timestamp: Date.now(), importance: 0.8 }
