    if (!agentRef.current || !goal) return;

    const newTask: Task = {
      id: Math.random().toString(36),
      goal,
      status: 'in_progress',
      subtasks: []
    };

    setState(prev => ({ 
      ...prev, 
      currentTask: newTask,
      status: AgentStatus.THINKING
    }));

    addThought({
      id: Math.random().toString(36),
      timestamp: Date.now(),
      content: `SYNAPSE_INIT: Orchestrating autonomous workflow for goal: "${goal}"`,
      type: 'plan'
    });

